function renderNightReport(){
 const h=document.querySelector('#nightReport');
 const e=escapeHTML;
 const matches=r=>(selected==='all'||r.property===selected)&&(platform==='all'||r.platform===platform);
 const active=nightReport.reviews.filter(r=>r.priority&&r.priority!=='historical'&&matches(r));
 const older=nightReport.reviews.filter(r=>(r.priority==='historical'||!r.priority)&&matches(r));
 const date=r=>r.publishedRelative?`${r.publishedRelative} (vist 7. oktober)`:r.publishedDate||r.publishedMonth||'Dato ikke tilgængelig';
 const card=r=>`<article><span class="type improve">${r.replyStatus==='unanswered'?'MANGLER SYNLIGT EJERSVAR':r.replyStatus==='answered'?'EJERSVAR SYNLIGT':'SVARSTATUS UKENDT'}</span><h3>${e(r.author)} · ${e(properties.find(p=>p.id===r.property).name)}</h3><div class="meta">${e(r.platform)}${r.score!=null?' · '+e(r.score)+'/'+e(r.scale):''} · ${e(date(r))}</div><p>${e(r.summary)}</p>${r.action?`<div class="suggestion">${e(r.action)}</div>`:''}<div class="meta">${e(r.replyEvidence)}</div><a href="${e(r.url)}" target="_blank" rel="noopener noreferrer">Åbn anmeldelsen eller profilen</a></article>`;
 h.innerHTML=`<div class="section-heading"><div><div class="eyebrow">KONTROLLERET · 7. OKTOBER 2026</div><h2>Det bør vi følge op på</h2></div><span class="tag">${active.length} anmeldelser med kritik</span></div><p class="section-intro">${active.length?`${active.length} gennemgåede anmeldelser med kritik har intet synligt ejersvar. Start med belysning og trappe, bruseren og smækkende døre.`:'Ingen ubesvaret kritik fremhævet for dette valg.'} Fundene er først registreret nu og er ikke nødvendigvis nye siden sidste tjek. Problemerne er gæsternes beskrivelser; de skal undersøges på stedet.</p><div class="feedback">${active.map(card).join('')}</div>${older.length?`<details style="margin-top:24px"><summary>Besvarede anmeldelser og ældre fund (${older.length})</summary><div class="feedback" style="margin-top:20px">${older.map(card).join('')}</div></details>`:''}<div style="margin-top:24px"><h3>Kontrollens dækning</h3>${nightReport.coverage.filter(c=>platform==='all'||c.platform===platform).map(c=>`<div class="source-row"><strong>${e(c.platform)}</strong><div>${e(c.detail)}</div><span>${e(c.status)}</span></div>`).join('')}</div><p class="footnote">Kontrollerede udgangspunkter fra 7. oktober 2026. <a href="checks/2026-10-07-manual-check.json">Se gemt datagrundlag</a>. <a href="checks/2026-10-07-summerhouse-baseline.json">Sommerhusets datagrundlag</a>. <a href="checks/2026-10-07-first-check.json">Tidligere tjek bevaret</a>. Ingen dokumenteret op- eller nedgang endnu. Ingen svar er sendt til gæster.</p>`;
}
