let topicCategory='all',topicSentiment='all',topicRoom='all';
function renderReviewTopics(){
 const host=document.querySelector('#reviewTopics');if(!host)return;
 const e=escapeHTML;
 const rows=reviewAspectEvidence.flatMap(item=>{
  const r=nightReport.reviews.find(r=>r.id===item.reviewId);if(!r)return [];
  const listing=airbnbListings.find(l=>l.url===r.url&&l.property===r.property);
  const room=item.roomNumber?'Værelse '+item.roomNumber:listing?'Type: '+listing.title:r.property==='jylkat'?'Bar / restaurant':'Værelse ikke oplyst';
  return item.aspects.map(a=>({...a,r,room}));
 }).filter(a=>(selected==='all'||a.r.property===selected)&&(platform==='all'||a.r.platform===platform));
 const rooms=[...new Set(rows.map(a=>a.room))].sort();if(!rooms.includes(topicRoom))topicRoom='all';
 const subset=rows.filter(a=>(topicRoom==='all'||a.room===topicRoom)&&(topicSentiment==='all'||a.sentiment===topicSentiment));
 const categories=Object.entries(reviewCategories).map(([id,label])=>({id,label,good:new Set(subset.filter(a=>a.category===id&&a.sentiment==='good').map(a=>a.r.id)).size,bad:new Set(subset.filter(a=>a.category===id&&a.sentiment==='bad').map(a=>a.r.id)).size})).sort((a,b)=>b.bad-a.bad||b.good-a.good);
 const details=subset.filter(a=>topicCategory==='all'||a.category===topicCategory);
 const unique=new Set(rows.map(a=>a.r.id)).size;
 host.innerHTML=`<div class="section-heading"><div><div class="eyebrow">HVOR SKAL VI SÆTTE IND?</div><h2>Ros og kritik efter emne</h2></div><span class="tag">${unique} gennemgåede anmeldelser</span></div><p class="section-intro">Klik på et emne for at se, hvad gæsterne konkret beskriver. Sted og platform følger valget øverst. En anmeldelse kan indeholde både ros og kritik og tælle under flere emner. Tallene gælder kun de ${unique} anmeldelser med vurderet tekst i dette udsnit; de er ikke hele anmeldelseshistorikken.</p><div class="topic-filters"><label>Vis<select id="topicSentiment"><option value="all">Ros og kritik</option><option value="bad" ${topicSentiment==='bad'?'selected':''}>Kun kritik</option><option value="good" ${topicSentiment==='good'?'selected':''}>Kun ros</option></select></label><label>Værelse / værelsestype<select id="topicRoom"><option value="all">Alle / ikke oplyst</option>${rooms.map(r=>`<option ${topicRoom===r?'selected':''} value="${e(r)}">${e(r)}</option>`).join('')}</select></label></div><div class="topic-grid"><button type="button" data-topic="all" aria-pressed="${topicCategory==='all'}"><strong>Alle emner</strong><span>Se hele udsnittet</span></button>${categories.map(c=>`<button type="button" data-topic="${c.id}" aria-pressed="${topicCategory===c.id}"><strong>${e(c.label)}</strong><span><b class="topic-bad">${c.bad} kritik</b> · <b class="topic-good">${c.good} ros</b></span></button>`).join('')}</div><h3>${topicCategory==='all'?'Konkrete observationer':e(reviewCategories[topicCategory])}</h3><p class="footnote">Værelsesnummer vises kun, hvis gæsten har oplyst det. Airbnb-opslag identificerer en værelsestype, ikke et bestemt fysisk værelse. “Værelse ikke oplyst” skal afklares, før en rengøringsklage knyttes til et værelse. Gæsternes beskrivelser skal undersøges på stedet.</p><div class="table-wrap"><table class="topic-table"><thead><tr><th>Sted / værelse</th><th>Emne</th><th>Gæstens oplevelse</th><th>Anmeldelse</th></tr></thead><tbody>${details.map(a=>`<tr><td><strong>${e(properties.find(p=>p.id===a.r.property).name)}</strong><span class="address">${e(a.room)}</span></td><td>${e(reviewCategories[a.category])}<span class="count ${a.sentiment==='bad'?'topic-bad':'topic-good'}">${a.sentiment==='bad'?'Kritik':'Ros'}</span></td><td>${e(a.detail)}${a.sentiment==='bad'&&a.room==='Værelse ikke oplyst'&&a.category==='clean'?'<span class="count">Afklar værelse og tidspunkt med gæsten eller bookinghistorikken.</span>':''}</td><td><a href="${e(a.r.url)}" target="_blank" rel="noopener noreferrer">${e(a.r.author)} · ${e(a.r.platform)}</a><span class="count">${e(a.r.publishedDate||a.r.publishedMonth||(a.r.publishedRelative? a.r.publishedRelative+' (vist '+a.r.observedAt.slice(0,10)+')':null)||'Dato ikke oplyst')}</span><span class="count">${a.r.replyStatus==='answered'?'Ejersvar synligt':a.r.replyStatus==='unanswered'?'Intet synligt ejersvar':'Svarstatus ukendt'}</span></td></tr>`).join('')||'<tr><td colspan="4">Ingen vurderede observationer for dette valg. Det betyder ikke, at der ingen anmeldelser findes.</td></tr>'}</tbody></table></div>`;
 host.querySelectorAll('[data-topic]').forEach(b=>b.addEventListener('click',()=>{topicCategory=b.dataset.topic;renderReviewTopics();host.querySelector(`[data-topic="${topicCategory}"]`).focus();}));
 host.querySelector('#topicSentiment').addEventListener('change',event=>{topicSentiment=event.target.value;renderReviewTopics();});
 host.querySelector('#topicRoom').addEventListener('change',event=>{topicRoom=event.target.value;renderReviewTopics();});
}
renderReviewTopics();

const teamNews={property:'summer',date:'2026-10-08',expiresOn:'2026-10-22',title:'Mega godt gået, team!',text:'Gamle Bryggeri er blevet Superhost på Airbnb! Jannie fortæller, at I har opfyldt kravene i perioden og løftet ratingen til 4,8. Tak for jeres arbejde med at give gæsterne en fantastisk oplevelse.',source:'Nyhed oplyst af Jannie 8. oktober. Periodens rating er ikke bekræftet som opslagets samlede bedømmelse.'};
function renderTeamCelebration(){
 const box=document.querySelector('#celebration');if(!box)return;
 const today=new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Copenhagen'});
 const fresh=nightReport.reviews.filter(r=>r.classification==='new_review'&&r.score===r.scale&&r.publishedDate&&r.publishedDate<=today&&Date.parse(today)-Date.parse(r.publishedDate)<=7*86400000&&(selected==='all'||selected===r.property)&&(platform==='all'||platform===r.platform)&&!reviewAspectEvidence.find(a=>a.reviewId===r.id)?.aspects.some(a=>a.sentiment==='bad')).sort((a,b)=>b.publishedDate.localeCompare(a.publishedDate))[0];
 const news=today<=teamNews.expiresOn&&(selected==='all'||selected===teamNews.property)&&(platform==='all'||platform==='Airbnb');
 box.hidden=!news&&!fresh;if(box.hidden)return;
 const e=escapeHTML;
 box.innerHTML=`<span class="celebration-spark" aria-hidden="true">🎆 ✨ 🎉</span><div><div class="eyebrow">DET SKAL VI FEJRE</div><h2>Mega godt gået, team!</h2>${news?`<p>${e(teamNews.text)}</p><small>${e(teamNews.source)}</small>`:`<p><strong>${e(properties.find(p=>p.id===fresh.property).name)} har fået ${fresh.score}/${fresh.scale}!</strong> ${e(fresh.summary||'Tak for jeres arbejde med gæsternes oplevelse.')}</p><a href="${e(fresh.url)}" target="_blank" rel="noopener noreferrer">Læs ${e(fresh.author)}s anmeldelse · ${e(fresh.publishedDate)}</a>`}</div>`;
}
renderTeamCelebration();
